 public void Pause(bool value){if(!value&&Arena.Instance.Setup.Open)return;Paused=value;Time.timeScale=value?0:1;if(!a)a=Arena.Instance;if(a&&a.Human)a.Human.GetComponent<HumanInput>().Capture(!value&&a.Match.Phase!=RoundPhase.MatchOver);if(pause!=null)RefreshVisibility();}
