 void Update(){if(Root==null)return;if(!a.Setup.Open&&!a.Research.Open){if(Keyboard.current?.f4Key.wasPressedThisFrame??false)diagnostics=!diagnostics;if(Keyboard.current?.hKey.wasPressedThisFrame??false)help=!help;}Visible(aiPanel,!a.Tutorial.Running&&(diagnostics||a.Client.Blocked||a.Client.LastRequestFailed||(a.Spectating&&a.LeftClient.LastRequestFailed)));Visible(controls,help);smoothFrame=Mathf.Lerp(smoothFrame,Time.unscaledDeltaTime,.06f);bool over=a.Match.Phase==RoundPhase.MatchOver;if(over&&!wasOver){a.Human.GetComponent<HumanInput>().Capture(false);Refresh();}wasOver=over;RefreshVisibility();Visible(hit,Time.unscaledTime<HitUntil&&!Paused);if(!Paused&&Time.unscaledTime>=nextRefresh){nextRefresh=Time.unscaledTime+.1f;Refresh();}if(Paused&&Time.unscaledTime>=nextRefresh){nextRefresh=Time.unscaledTime+.5f;Set(perf,$"{1/Mathf.Max(.001f,smoothFrame):0} FPS   ·   {smoothFrame*1000:0.0} ms / frame");}UpdateAim();UpdateCombat();UpdateIntent();}
