 void Refresh(){RefreshCount++;Set(score,$"{a.Match.HumanWins}  :  {a.Match.AIWins}");Set(round,$"ROUND {a.Match.Round:00}   /   {a.LayoutName.ToUpperInvariant()}   /   FIRST TO {a.Match.WinsRequired}"+(a.Match.RivalBoost>0&&!a.Tutorial.Running?$"   /   {a.RightName.ToUpperInvariant()} +{a.Match.RivalBoost*100:0}%":""));Set(roundClock,a.Tutorial.Running?"TRAINING":a.Match.SuddenDeath?"SUDDEN DEATH":a.Match.TimedRounds?$"{Mathf.FloorToInt(a.Match.RoundRemaining/60):00}:{Mathf.FloorToInt(a.Match.RoundRemaining%60):00}":"NO TIME LIMIT");roundClock.EnableInClassList("urgent",a.Match.SuddenDeath);Set(leftTitle,a.Spectating?a.LeftName.ToUpperInvariant():"YOU");Set(rightTitle,a.RightName.ToUpperInvariant());bool offline=a.Client.LastRequestFailed;Set(connection,"●  "+a.RightName.ToUpperInvariant()+" / "+Runtime(a.Client));connection.EnableInClassList("orange",offline||!a.Experiments.Ready);Set(decision,!a.Experiments.Ready?"Open F2 to review settings":a.Client.WaitStatus);Set(latency,a.Telemetry.RecordingError!=null?"Recording error · check storage":$"Last {a.Client.LastLatency:0} ms · {a.Telemetry.StatsFor(a.RightName).executed_decisions} played · {a.Telemetry.StatsFor(a.RightName).stale_responses} outdated");Visible(secondAI,a.Spectating);Set(secondAI,a.Spectating?$"{a.LeftName.ToUpperInvariant()} / {Runtime(a.LeftClient)} · {a.LeftClient.WaitStatus}\nLast {a.LeftClient.LastLatency:0} ms · {a.Telemetry.StatsFor(a.LeftName).executed_decisions} played · {a.Telemetry.StatsFor(a.LeftName).stale_responses} outdated":"");Set(controls,a.Spectating?"SPECTATOR   /   Fixed arena view     ESC  Pause / matchup     TAB  Statistics     F2  Experiment lab":"WASD / ARROWS  Move     F  Push / throw     E  Grab / drop     SHIFT  Dodge     SPACE  Jump     AUTO AIM");Set(held,a.Spectating?"SPECTATING / AI VS AI":a.Human.Held?a.Human.Held.Kind.ToUpperInvariant()+" / "+(a.Human.Held.Kind=="barrel"?"HEAVY":a.Human.Held.Kind=="chair"?"LIGHT":"BALANCED"):"HANDS FREE");Set(dodge,a.Spectating?"INDEPENDENT MODELS":Time.time<a.Human.StunnedUntil?"Recovering balance…":Time.time<a.Human.NextDodge?$"Dodge in {a.Human.NextDodge-Time.time:0.0}s":"SHIFT / DODGE");var nearest=a.Human.Held?null:a.Human.Nearest();Set(interaction,a.Spectating?"FIXED ARENA VIEW":a.Human.Held?"F   THROW "+a.Human.Held.Kind.ToUpperInvariant():nearest?"E   GRAB "+nearest.Kind.ToUpperInvariant():"F   PUSH");Set(edge,input.RestartHeld>0?$"HOLD R TO RESTART · {100*input.RestartHeld/HumanInput.RestartHoldSeconds:0}%":a.Match.SuddenDeath?"STAY INSIDE THE ORANGE BOUNDARY":!a.Spectating&&a.Human.Edge<1.8f?"OPEN EDGE · MOVE INWARD":"");bool countdown=a.Match.Phase==RoundPhase.Countdown;bool fightCall=a.Match.Phase==RoundPhase.Fight&&!a.Match.Practice&&Time.time-a.Match.FightStarted<.9f;Visible(center,(countdown||fightCall||a.Match.Phase==RoundPhase.Winner||a.Match.Practice)&&!a.Tutorial.Running);Set(banner,a.Match.Practice?"EXECUTOR LAB":countdown?Mathf.CeilToInt(a.Match.PhaseEnds-Time.time).ToString():a.Match.Announcement);banner.EnableInClassList("round-message",!countdown&&!fightCall);Set(subline,a.Match.Practice?"PRACTICE / SCORING DISABLED":countdown?(a.Spectating?$"{a.LeftName} VS {a.RightName} · SAME RULES".ToUpperInvariant():"SEND "+a.RightName.ToUpperInvariant()+" OFF. STAY ON THE ROOF."):fightCall?"STAY ON THE ROOF":a.Match.LastRoundWinner||a.Match.Phase!=RoundPhase.Winner?"NEXT ROUND IN A MOMENT":"NO POINT AWARDED · NEXT ROUND IN A MOMENT");if(statsVisible)RefreshResults();}
 static string Runtime(LayaClient client)=>client.Provider==AIProvider.Laya?client.Model+" · "+client.Backend:client.Model;
 void RefreshResults(){Set(resultScore,$"{a.Match.HumanWins} — {a.Match.AIWins}");Set(leftStatsTitle,a.Spectating?a.LeftName.ToUpperInvariant():"YOU");Set(rightStatsTitle,a.RightName.ToUpperInvariant());Visible(distributionPlayer,a.Spectating);string actor=a.Spectating&&distributionPlayer.index==1?a.LeftName:a.RightName;Set(distributionTitle,actor.ToUpperInvariant()+" CHOICES");var aiStats=a.Telemetry.StatsFor(actor);var distribution=aiStats.action_counts;var h=a.Human;var l=a.AI;Set(resultTitle,a.Match.Phase==RoundPhase.MatchOver?a.Match.Announcement:"Match snapshot");string[] lv={a.Match.HumanWins.ToString(),a.Match.HumanSelfOuts.ToString(),$"{h.Grabs} / {h.Throws}",h.Throws>0?$"{100f*h.Hits/h.Throws:0}%":"—",h.Pushes.ToString(),h.Dodges.ToString(),$"{h.EdgeTime:0.0}s",$"{h.EdgeSum/Mathf.Max(.01f,h.Samples):0.0} m",a.Match.HumanEnvironmentalKOs.ToString()};string[] rv={a.Match.AIWins.ToString(),a.Match.AISelfOuts.ToString(),$"{l.Grabs} / {l.Throws}",l.Throws>0?$"{100f*l.Hits/l.Throws:0}%":"—",l.Pushes.ToString(),l.Dodges.ToString(),$"{l.EdgeTime:0.0}s",$"{l.EdgeSum/Mathf.Max(.01f,l.Samples):0.0} m",a.Match.AIEnvironmentalKOs.ToString()};for(int i=0;i<9;i++){Set(left[i],lv[i]);Set(right[i],rv[i]);}int max=1;foreach(int n in distribution)max=Mathf.Max(max,n);for(int i=0;i<actionNames.Length;i++){Set(counts[i],distribution[i].ToString());bars[i].style.width=Length.Percent(100f*distribution[i]/max);}Set(resultInfo,$"{actor}: {aiStats.executed_decisions} executed decisions   ·   {aiStats.total_latency_ms/Mathf.Max(1,aiStats.executed_decisions):0} ms mean model latency   ·   F3 exports full decision details");Visible(rematch,a.Match.Phase==RoundPhase.MatchOver);}
 void UpdateAim(){bool show=a.Guide&&a.Guide.HasAim&&!Paused;Visible(crosshair,show);if(!show)return;var screen=sceneCamera.WorldToScreenPoint(a.Guide.AimPoint);Visible(crosshair,screen.z>0);crosshair.style.left=screen.x/Screen.width*Root.resolvedStyle.width-10;crosshair.style.top=(1-screen.y/Screen.height)*Root.resolvedStyle.height-10;}
 void UpdateCombat(){var f=a.Human;Visible(tutorialPanel,a.Tutorial.Running);if(a.Tutorial.Running)Set(tutorialText,a.Tutorial.Instruction);
  dodgeFill.style.width=Length.Percent(100*Mathf.Clamp01(1-(f.NextDodge-Time.time)/1.1f));pushFill.style.width=Length.Percent(100*Mathf.Clamp01(1-(f.NextPush-Time.time)/.78f));
  Set(pushStatus,f.WindingUp?f.Attack.ToUpperInvariant()+" / COMMITTED":Time.time<f.RecoveryUntil?"RECOVERING":Time.time<f.NextPush?$"F / PUSH IN {f.NextPush-Time.time:0.0}s":"F / PUSH");
  bool show=!Paused&&!a.Setup.Open&&!a.Spectating&&a.AI.WindingUp;Visible(threat,show);if(show){Set(threatText,a.AI.Attack=="push"?"PUSH INCOMING":"THROW INCOMING");var screen=sceneCamera.WorldToScreenPoint(a.AI.transform.position+Vector3.up*2.3f);Visible(threat,screen.z>0);threat.style.left=Mathf.Clamp(screen.x/Screen.width*Root.resolvedStyle.width-80,12,Root.resolvedStyle.width-180);threat.style.top=Mathf.Clamp((1-screen.y/Screen.height)*Root.resolvedStyle.height,110,Root.resolvedStyle.height-100);}
 }
 void UpdateIntent(){bool on=IntentLabels&&!Paused&&!a.Setup.Open&&!a.Research.Open&&!a.Tutorial.Running&&a.Match.Phase==RoundPhase.Fight;
  for(int i=0;i<2;i++){var executor=i==0?a.LeftExecutor:a.Executor;var client=i==0?a.LeftClient:a.Client;var fighter=i==0?a.Human:a.AI;bool controlled=i==0?a.Spectating&&a.LeftBrain.Enabled:a.Brain.Enabled;string text=null;
   if(on&&controlled&&!(fighter.WindingUp&&!a.Spectating&&i==1)){if(executor.Running||executor.Started>0&&Time.time-executor.Started<.7f)text=intentNames[(int)executor.Selected];else if(client.Busy)text="THINKING"+new string('.',1+(int)(Time.unscaledTime*3)%3);}
   Visible(intents[i],text!=null);if(text==null)continue;Set(intentText[i],text);var screen=sceneCamera.WorldToScreenPoint(fighter.transform.position+Vector3.up*2.75f);Visible(intents[i],screen.z>0);intents[i].style.left=screen.x/Screen.width*Root.resolvedStyle.width-50;intents[i].style.top=(1-screen.y/Screen.height)*Root.resolvedStyle.height-12;}
 }
 void OnApplicationFocus(bool focus){if(!focus&&a&&System.Array.IndexOf(System.Environment.GetCommandLineArgs(),"--pg-benchmark")<0)Pause(true);}
